  type TokenType = Value
  val STRING = Value("string")
  val NUMERIC = Value("numeric")
  val TEMPORAL = Value("temporal")
  val STRUCTURED = Value("structured")
  val BINARY = Value("binary")
  val NULL = Value("null")
}

// ============================================================================
// Protocol definitions
// ============================================================================

trait Tokenizable {
  def toToken: String
}

trait HasLength {
  def length: Int
}

trait TokenProcessor[-T] {
  def process(item: T): Unit
}

// ============================================================================
// Core Token Classes
// ============================================================================

case class Token(value: String, tokenType: TokenType.TokenType, metadata: Map[String, Any] = Map.empty) {
  def withMetadata(kwargs: (String, Any)*): Token = {
    copy(metadata = metadata ++ kwargs.toMap)
  }
}

class MutableTokenBatch(var tokens: mutable.ListBuffer[Token] = mutable.ListBuffer.empty, private var _processed: Boolean = false) {
  def add(token: Token): Unit = {
    if (_processed) throw new RuntimeException("Batch already processed")
    tokens += token
  }

  def markProcessed(): Unit = {
    _processed = true
  }
}

// ============================================================================
// Generic Container Classes
// ============================================================================

class TokenContainer[+T](items: Seq[T]) {
  private val _items: Seq[T] = items

  def getAll: Seq[T] = _items

  def mapTokens(func: T => String): Seq[String] = {
    _items.map(func)
  }
}

class TokenSink[-T] {
  private val _received = mutable.ListBuffer[Any]()

  def receive(item: T): Unit = {
    _received += item
  }

  def drain(): List[Any] = {
    val result = _received.toList
    _received.clear()
    result
  }
}

class BivariantHandler[T](var _value: T) {
  def get: T = _value

  def set(value: T): Unit = {
    _value = value
  }

  def transform(func: T => T): T = {
    _value = func(_value)
    _value
  }
}

// ============================================================================
// Tokenizer Implementations
// ============================================================================

abstract class BaseTokenizer[T] {
  def tokenize(value: T): Token

  def tokenizeBatch(values: Iterable[T]): Iterator[Token] = {
    values.iterator.map(tokenize)
  }
}

class StringTokenizer(encoding: String = "utf-8", normalizer: String => String = identity) 
  extends BaseTokenizer[Either[String, Array[Byte]]] {

  override def tokenize(value: Either[String, Array[Byte]]): Token = {
    val strValue = value match {
      case Right(bytes) => new String(bytes, encoding)
      case Left(str) => str
    }

    val normalized = normalizer(strValue)
    Token(normalized, TokenType.STRING)
  }

  def tokenize(value: String): Token = tokenize(Left(value))
  def tokenize(value: Array[Byte]): Token = tokenize(Right(value))
}

class NumericTokenizer(precision: Int = 6, formatOptions: Map[String, Any] = Map.empty) 
  extends BaseTokenizer[Number] {

  override def tokenize(value: Number): Token = {
    val strValue = value match {
      case d: java.math.BigDecimal => String.format(s"%.${precision}f", d)
      case f: java.lang.Float => String.format(s"%.${precision}f", f)
      case d: java.lang.Double => String.format(s"%.${precision}f", d)
      case i: java.lang.Integer => i.toString
      case l: java.lang.Long => l.toString
      case _ => value.toString
    }

    Token(strValue, TokenType.NUMERIC, Map("original_type" -> value.getClass.getSimpleName))
  }

  def tokenize(value: Int): Token = tokenize(Integer.valueOf(value))
  def tokenize(value: Double): Token = tokenize(java.lang.Double.valueOf(value))
  def tokenize(value: BigDecimal): Token = tokenize(value.bigDecimal)
}

class TemporalTokenizer(formatStr: Option[String] = None) 
  extends BaseTokenizer[java.time.temporal.Temporal] {

  private val ISO_FORMAT = DateTimeFormatter.ISO_DATE_TIME
  private val DATE_FORMAT = DateTimeFormatter.ISO_DATE

  override def tokenize(value: java.time.temporal.Temporal): Token = {
    val fmt = formatStr.map(DateTimeFormatter.ofPattern).getOrElse {
      value match {
        case _: LocalDateTime => ISO_FORMAT
        case _: LocalDate => DATE_FORMAT
        case _ => DATE_FORMAT
      }
    }

    val strValue = fmt.format(value)
    Token(strValue, TokenType.TEMPORAL)
  }
}

// ============================================================================
// Advanced: Union Types and Overloads
// ============================================================================

class UniversalTokenizer {
  private val stringTokenizer = new StringTokenizer()
  private val numericTokenizer = new NumericTokenizer()
  private val temporalTokenizer = new TemporalTokenizer()

  def tokenize(value: String): Token = stringTokenizer.tokenize(value)
  def tokenize(value: Array[Byte]): Token = stringTokenizer.tokenize(value)
  def tokenize(value: Int): Token = numericTokenizer.tokenize(value)
  def tokenize(value: Double): Token = numericTokenizer.tokenize(value)
  def tokenize(value: BigDecimal): Token = numericTokenizer.tokenize(value)
  def tokenize(value: java.time.temporal.Temporal): Token = temporalTokenizer.tokenize(value)
  def tokenize(value: Tokenizable): Token = Token(value.toToken, TokenType.STRUCTURED)

  def tokenize(value: Option[Any]): Token = value match {
    case Some(v) => tokenizeAny(v)
    case None => Token("NULL", TokenType.NULL)
  }

  def tokenizeAny(value: Any): Token = value match {
    case null => Token("NULL", TokenType.NULL)
    case v: Tokenizable => tokenize(v)
    case v: String => tokenize(v)
    case v: Array[Byte] => tokenize(v)
    case v: Int => tokenize(v)
    case v: Double => tokenize(v)
    case v: BigDecimal => tokenize(v)
    case v: java.time.temporal.Temporal => tokenize(v)
    case _ => Token(value.toString, TokenType.STRING, Map("fallback" -> true))
  }
}

